
:root{--bg:#dde1e7;--soft:#f2f4f7;--base:#e8ebf0;--inset:inset 3px 3px 7px rgba(163,177,198,.55),inset -3px -3px 7px rgba(255,255,255,.9);--ink:#292d30;--pink:#f774b2;--pk:#fbe0ee;--mut:#6a7076;--ln:#e6e8ec;--sh:6px 6px 14px rgba(163,177,198,.5),-4px -4px 11px rgba(255,255,255,.9)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.4 system-ui,"Segoe UI",Roboto,sans-serif;display:flex;justify-content:center}
.phone{width:100%;max-width:430px;min-height:100vh;background:var(--base);display:flex;flex-direction:column}
#app{flex:1;display:flex;flex-direction:column}
header{display:flex;align-items:center;justify-content:space-between;padding:14px 16px 4px}header h1{font-size:16px;font-weight:600;margin:0}.heading{flex:1;min-width:0;text-align:center;padding:0 6px}.heading .greeting{font-size:12px;font-weight:600;margin-bottom:3px}.heading .mode{font-size:11px;color:var(--mut);font-weight:400}.header-actions{display:flex;gap:8px;flex:none}
.ib{width:34px;height:34px;border-radius:50%;border:0;background:var(--soft);box-shadow:var(--sh);display:grid;place-items:center;color:var(--ink);cursor:pointer;padding:0;flex:none}
main{flex:1;padding:8px 16px 16px;display:flex;flex-direction:column;gap:10px}
.card{background:var(--soft);border-radius:20px;padding:12px 14px;box-shadow:var(--sh)}
.row{display:flex;align-items:center;gap:8px}.sp{justify-content:space-between}.grow{flex:1;min-width:0}.mut{color:var(--mut);font-size:12px}.big{font-size:20px}
.btn{height:32px;padding:0 14px;border-radius:16px;border:0;background:var(--soft);box-shadow:var(--sh);color:var(--ink);font-family:inherit;font-size:13px;font-weight:500;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px}
.btn.pk{background:var(--pink);color:var(--ink)}.btn.dk{background:var(--ink);color:#fff}.btn.ol{box-shadow:inset 0 0 0 1.5px var(--pink),var(--sh);color:#a8336f}.btn.rd{box-shadow:inset 0 0 0 1.5px #f0c4cc,var(--sh);color:#b02a43}.btn.sm{height:28px;font-size:12px;padding:0 11px}
.chip{font-size:11px;padding:1px 9px;border-radius:12px;background:#fff;border:1px solid var(--ln);color:var(--mut)}.chip.pk{background:var(--pk);border-color:var(--pk);color:#b0356f}.meta{display:flex;gap:5px;flex-wrap:wrap;margin-top:4px}
input,select{width:100%;height:38px;border:0;border-radius:14px;background:var(--base);box-shadow:var(--inset);padding:0 12px;font:inherit;color:var(--ink)}
label{font-size:12px;color:var(--mut);display:block;margin:8px 2px 4px}
:focus-visible{outline:2px solid var(--pink);outline-offset:2px}
.av{width:38px;height:38px;border-radius:50%;background:var(--pk);color:#b0356f;display:grid;place-items:center;font-weight:700;flex:none}
.ck{width:22px;height:22px;border-radius:50%;border:2px solid #cfd3d8;background:var(--soft);cursor:pointer;flex:none;padding:0;display:grid;place-items:center;color:var(--ink)}.ck[aria-checked=true]{background:var(--pink);border-color:var(--pink)}
.rs{text-decoration:line-through;color:var(--mut)}.bar{height:6px;background:#e4e6ea;border-radius:4px;overflow:hidden;margin-top:4px}.bar i{display:block;height:100%;background:var(--pink)}
nav{position:sticky;bottom:0;display:flex;gap:8px;padding:10px 14px 14px;background:var(--base)}
nav button{height:40px;width:40px;border-radius:20px;border:0;background:var(--soft);box-shadow:var(--sh);display:flex;align-items:center;justify-content:center;gap:6px;color:var(--mut);font:600 13px system-ui;cursor:pointer;padding:0}nav span{display:none}
nav button:not(.on){flex:0 0 40px}nav .on{flex:1;min-width:0;width:auto;background:var(--pk);color:#8f2a5c;box-shadow:var(--inset)}nav .on span{display:inline}
.ov{position:fixed;inset:0;background:rgba(20,20,40,.35);display:flex;align-items:flex-end;justify-content:center;z-index:9}
.sheet{width:100%;max-width:430px;background:var(--soft);border-radius:24px 24px 0 0;padding:18px 16px 22px;display:flex;flex-direction:column;gap:8px}.sheet .btn{justify-content:flex-start;height:38px}
#aviso{display:none;margin:8px 16px 0;padding:12px;border-radius:14px;background:#e3edf7;color:#23435e;gap:10px;align-items:flex-start;overflow-wrap:anywhere}#aviso.on{display:flex}#aviso.erro{background:#fbe5e8;color:#882039}#aviso .texto{flex:1;min-width:0}#aviso button{border:0;background:transparent;color:inherit;font:inherit;font-size:20px;line-height:1;cursor:pointer;padding:0 2px}
.msg{padding:8px 12px;border-radius:16px;max-width:85%;white-space:pre-wrap}.me{align-self:flex-end;background:var(--pink);color:var(--ink)}.ia{align-self:flex-start;background:var(--soft);box-shadow:var(--sh)}
.btn:disabled{opacity:.6;cursor:wait}.ia-progress{display:flex;align-items:center;gap:10px;margin-top:10px;padding:12px;border-radius:14px;background:var(--pk);color:#7a2854;font-size:13px}.spinner{width:18px;height:18px;border:2px solid #d9aac2;border-top-color:#8f2a5c;border-radius:50%;animation:girar 1s linear infinite;flex:none}@keyframes girar{to{transform:rotate(360deg)}}
.grid{display:flex;flex-direction:column;gap:10px}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}

/* Mantém as cores de repouso e realça interação por mouse e teclado. */
.btn,.ib,nav button{transition:background-color .15s ease,filter .15s ease}
.btn:not(:disabled):is(:hover,:focus-visible){background:#dce1e8}
.btn.pk:not(:disabled):is(:hover,:focus-visible){background:#ec60a2}
.btn.dk:not(:disabled):is(:hover,:focus-visible){background:#454b50}
.btn.ol:not(:disabled):is(:hover,:focus-visible){background:#f5d6e5}
.btn.rd:not(:disabled):is(:hover,:focus-visible){background:#f4dce1}
.btn:not(:disabled):active{filter:brightness(.92)}
.ib:not(:disabled):is(:hover,:focus-visible),nav button:not(:disabled):is(:hover,:focus-visible){background:#dce1e8}
nav button.on:is(:hover,:focus-visible){background:#f3c9dd}
.ib:active,nav button:active{filter:brightness(.92)}
.sheet-error{margin:0;color:#882039;font-size:13px}

.dash-ring-row{display:flex;align-items:center;justify-content:center;gap:20px;flex-wrap:wrap;margin-top:10px}
.dash-ring{width:150px;height:150px;flex:none}
.dash-legend{display:grid;gap:10px;font-size:13px}
.dash-dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}
.dash-label{display:flex;justify-content:space-between;gap:8px;margin:12px 0 6px;font-size:13px}
.dash-track{height:12px;border-radius:10px;background:#dce1e8;overflow:hidden}
.dash-fill{height:100%;border-radius:10px;background:var(--pink)}
.dash-scale{display:flex;justify-content:space-between;gap:8px;color:var(--mut);font-size:11px;margin-top:8px}
.dash-empty{text-align:center;color:var(--mut);font-size:12px;margin:10px 0 0}

/* Mascote aprovada, enquadrada na cintura somente na tela de login. */
.login-main{justify-content:center;gap:10px;padding-top:18px;padding-bottom:24px}
.login-mascote{position:relative;width:260px;height:200px;align-self:center;overflow:hidden;flex:none;mix-blend-mode:multiply;mask-image:linear-gradient(#000 90%,transparent);-webkit-mask-image:linear-gradient(#000 90%,transparent)}
.login-mascote img{position:absolute;width:600px;max-width:none;height:auto;left:-320px;top:-48px}
.login-main .login-logo{margin:-8px 0 -6px}
.login-links{display:flex;flex-direction:column;align-items:center;gap:8px;margin-top:4px}
.login-links .btn{min-height:36px;height:auto;padding:8px 14px;background:none;box-shadow:none;color:#9c326b;text-align:center}
.login-links .forgot{font-size:12px;text-decoration:underline;text-underline-offset:3px}
@media(max-height:650px){.login-main{gap:6px;padding-top:8px;padding-bottom:14px}.login-mascote{height:155px;width:220px}.login-mascote img{width:480px;left:-252px;top:-38px}}

/* Padrão provisório aprovado para o login. */
body.login-screen{background:var(--base);overflow-x:hidden}
.login-main{position:relative;isolation:isolate}
.login-main .login-logo{position:relative}
.login-main .login-logo::before{content:"";position:absolute;z-index:-1;pointer-events:none;top:-238px;bottom:-6px;left:50%;width:100vw;transform:translateX(-50%);background:url("data:image/png;base64,") center top/100% 200% no-repeat;mask-image:linear-gradient(to bottom,#000 60%,transparent 100%);-webkit-mask-image:linear-gradient(to bottom,#000 60%,transparent 100%)}
@media(max-height:650px){.login-main .login-logo::before{top:-181px}}

body.login-screen .phone{width:100%;max-width:none;background:transparent}
body.login-screen .login-main{width:100%;max-width:430px;margin:0 auto}
.login-main>.card{background:rgba(248,241,252,.20);box-shadow:0 6px 20px rgba(83,94,125,.10);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px)}
.login-main>.card input{background:rgba(255,255,255,.20);color:#39283f;border:1px solid rgba(132,95,155,.28);box-shadow:inset 1px 2px 5px rgba(87,65,108,.10)}
.login-main label{color:#39283f;font-weight:600}
.login-main .btn.pk{background:#ddb9e8;color:#39283f}
.login-main .btn.pk:not(:disabled):is(:hover,:focus-visible){background:#d2a5df}
.login-links .btn{color:#75456f}

/* Mostrar ou ocultar a senha sem alterar as dimensões do campo. */
.senha-campo{position:relative;height:38px}
.senha-campo input{padding-right:46px}
.senha-campo input::-ms-reveal{display:none}
.senha-olho{position:absolute;right:3px;top:0;width:38px;height:38px;padding:8px;border:0;border-radius:12px;background:transparent;color:#75456f;display:grid;place-items:center;cursor:pointer}
.senha-olho:hover{background:rgba(132,95,155,.10)}
.senha-olho svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.senha-olho[aria-pressed="false"] .olho-risco{display:none}

/* Perguntas frequentes: painel de ajuda sem sair da tela atual. */
.faq-dialog{width:calc(100% - 32px);max-width:430px;max-height:calc(100dvh - 32px);padding:0;border:0;border-radius:20px;background:var(--soft);color:var(--ink);font:inherit;box-shadow:0 12px 40px rgba(30,25,50,.24);overflow:auto}
.faq-dialog::backdrop{background:rgba(20,20,40,.35)}
.faq-top{position:sticky;top:0;z-index:1;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px;background:var(--soft);border-bottom:1px solid var(--ln)}
.faq-top h2{margin:0;font-size:17px}.faq-top .ib{flex:none}
.faq-content{padding:0 16px 18px}.faq-intro{color:var(--mut);font-size:13px;margin:14px 0}
.faq-content details{border-bottom:1px solid #d5d9e1;padding:12px 0}
.faq-content summary{cursor:pointer;font-weight:600;line-height:1.5;padding:3px 0}
.faq-content summary:focus-visible{outline:2px solid var(--pink);outline-offset:3px;border-radius:4px}
.faq-content details[open] summary{color:#75456f}
.faq-content details p{margin:10px 0 2px;line-height:1.65;overflow-wrap:anywhere}

/* Clareza dos controles, preservando os ícones de 40 px da navegação. */
.nav-item{flex:0 0 40px;min-width:0;text-align:center}.nav-item.is-current{flex:1}
nav .nav-item button{width:40px;height:40px}nav .nav-item.is-current button{width:100%}
.nav-item small{display:block;font-size:10px;line-height:13px;margin-top:5px;white-space:nowrap;color:var(--mut)}.nav-item.is-current small{visibility:hidden}
.profile-context{margin:4px 16px 0;color:#75456f;text-align:center;font-size:12px;overflow-wrap:anywhere}
header h1:focus{outline:none}.field-error{margin:5px 3px 9px;color:#882039;font-size:12px}.field-invalid{outline:2px solid #bd526b;outline-offset:1px}
.ov{width:100%;height:100%;max-width:none;max-height:none;margin:0;padding:0;border:0;background:transparent;color:var(--ink);font:inherit}.ov:not([open]){display:none}.ov::backdrop{background:rgba(20,20,40,.35)}
.ov .sheet{max-height:calc(100dvh - 24px);overflow:auto}.ov .sheet>input{flex:none}
.ck{width:40px;height:40px;border:0;background:transparent;position:relative}.ck::before{box-sizing:border-box;content:"";position:absolute;width:22px;height:22px;border:2px solid #cfd3d8;border-radius:50%;background:var(--soft)}.ck[aria-checked=true]{background:transparent}.ck[aria-checked=true]::before{background:var(--pink);border-color:var(--pink)}.ck svg{z-index:1}
.audio-control,.completion-control{display:flex;flex-direction:column;align-items:center;flex:none;width:40px;gap:2px}.audio-control small,.completion-control small{font-size:9px;color:var(--mut);line-height:12px}.audio-control small{color:#75456f}.audio-control .ib{margin:3px}
.task-header{align-items:flex-start}.task-title{padding-top:3px;overflow-wrap:anywhere}.step-row{align-items:center}.step-row>.grow{overflow-wrap:anywhere}
.task-header .task-view{align-self:flex-start;flex:none;width:76px;height:auto;min-height:36px;margin-top:0;padding:5px 8px;white-space:normal;line-height:1.2;text-align:center}.task-tools{border-top:1px solid #dce0e7;padding-top:12px;margin-top:10px}.task-tools .row{flex-wrap:wrap}.tools-label{font-size:11px;color:var(--mut);margin:0 0 7px}.tea-guide{margin:0;color:#75456f;font-size:13px}.tea-screen .task-title>b{font-size:16px}.tea-screen .task-view{min-height:36px}.task-filters{flex-wrap:wrap}.task-toolbar{display:flex;flex-direction:column;gap:10px}.task-create{align-self:flex-end}
.chat-log{min-height:160px;overflow-wrap:anywhere}.chat-composer{position:sticky;bottom:82px;padding:10px 14px;background:var(--base);z-index:2}.chat-wait{margin-top:0;align-self:flex-start}.chat-error{padding:10px 12px;background:#fbe5e8;color:#882039;border-radius:14px;max-width:100%}.chat-error p{margin:0 0 8px}
.chat-log .msg{flex:none}.chat-log .ia-progress{flex:none}.chat-end{height:1px;flex:none}.btn[aria-busy=true]{cursor:wait}
@media(min-width:760px){
 body:not(.login-screen) .phone{max-width:1060px;min-height:100dvh}
 body:not(.login-screen) header{padding:22px 32px 8px}body:not(.login-screen) header h1{font-size:20px}
 body:not(.login-screen) main{padding:20px 32px 24px}
 .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));align-items:start;gap:18px}
 main[data-nx]>.card{max-width:640px;width:100%;align-self:center}
 nav{width:100%;max-width:680px;align-self:center}.profile-context{margin-top:6px}
 .chat-log{width:100%;max-width:850px;align-self:center}.chat-composer{width:100%;max-width:850px;align-self:center;padding:12px 32px}
 .task-toolbar{flex-direction:row;justify-content:space-between;align-items:center}.task-create{align-self:auto}
 .faq-dialog{max-width:520px}
}
nav{z-index:3}.ck{isolation:isolate}


/* Materiais de apoio: estilos exclusivos da nova área. */
.material-toolbar{flex-wrap:wrap}.material-toolbar p{flex:1;min-width:140px;margin:0}.material-toolbar .btn{flex:none}
.material-card{overflow:hidden}.material-image{position:relative;aspect-ratio:16/7;border-radius:14px;overflow:hidden;background:linear-gradient(135deg,#efdaee,#e1eaf4);margin-bottom:12px}
.material-image img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.material-fallback{height:100%;display:grid;place-items:center;color:#80517e}
.material-heading{align-items:flex-start}.material-heading h2{margin:0;font-size:16px;overflow-wrap:anywhere}.material-card .meta{gap:6px}.material-description{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}
.material-actions{flex-wrap:wrap}.material-actions a{text-decoration:none}.material-actions .btn{min-height:34px;height:auto;padding-top:7px;padding-bottom:7px;white-space:normal;text-align:center}
.material-check{display:flex;align-items:center;gap:9px;color:var(--ink);cursor:pointer;margin:12px 0}.material-check input{width:20px;height:20px;flex:none;padding:0;box-shadow:none;accent-color:#a84e8b}.material-check span{overflow-wrap:anywhere}
.material-destinations{border:1px solid #cdd2dd;border-radius:14px;padding:8px 12px;margin:15px 0 0}.material-destinations legend{font-size:12px;color:var(--mut)}
.material-preview-button{margin-top:10px}main[data-nx] textarea{width:100%;border:0;border-radius:14px;background:var(--base);box-shadow:var(--inset);padding:10px 12px;font:inherit;color:var(--ink);resize:vertical;min-height:82px}
@media(max-width:360px){nav:has([data-v="materiais"]) .nav-item.is-current button span{display:none}nav:has([data-v="materiais"]) .nav-item.is-current small{visibility:visible}}




/* Prévia: somente escala vertical do fundo, mantendo o centro. */
.login-main .login-logo::before{transform:translateX(-50%) scaleY(1.4);transform-origin:center center;mask-image:linear-gradient(to bottom,transparent 0%,rgba(0,0,0,.08) 5%,rgba(0,0,0,.35) 12%,rgba(0,0,0,.75) 22%,#000 32%,#000 55%,rgba(0,0,0,.75) 68%,rgba(0,0,0,.35) 82%,rgba(0,0,0,.08) 94%,transparent 100%);-webkit-mask-image:linear-gradient(to bottom,transparent 0%,rgba(0,0,0,.08) 5%,rgba(0,0,0,.35) 12%,rgba(0,0,0,.75) 22%,#000 32%,#000 55%,rgba(0,0,0,.75) 68%,rgba(0,0,0,.35) 82%,rgba(0,0,0,.08) 94%,transparent 100%)}



/* Protege o conteúdo das áreas reservadas do aparelho, sem alterar os espaços existentes. */
:root{--safe-top:env(safe-area-inset-top,0px);--safe-right:env(safe-area-inset-right,0px);--safe-bottom:env(safe-area-inset-bottom,0px);--safe-left:env(safe-area-inset-left,0px)}
.phone{padding:var(--safe-top) var(--safe-right) var(--safe-bottom) var(--safe-left)}
nav{bottom:var(--safe-bottom)}
.chat-composer{bottom:calc(82px + var(--safe-bottom))}
.ov{padding:var(--safe-top) var(--safe-right) var(--safe-bottom) var(--safe-left)}
.ov .sheet{max-height:calc(100dvh - 24px - var(--safe-top) - var(--safe-bottom))}
.faq-dialog{top:var(--safe-top);right:var(--safe-right);bottom:var(--safe-bottom);left:var(--safe-left);width:calc(100% - 32px - var(--safe-left) - var(--safe-right));max-height:calc(100dvh - 32px - var(--safe-top) - var(--safe-bottom))}
